import React, { useEffect, useRef, useState } from "react";
import "codemirror/mode/javascript/javascript";
import "codemirror/mode/python/python";
import "codemirror/mode/clike/clike";
import "codemirror/theme/dracula.css";
import "codemirror/addon/edit/closetag";
import "codemirror/addon/edit/closebrackets";
import "codemirror/lib/codemirror.css";
import CodeMirror from "codemirror";
import Select from "react-select";
import axios from "axios"; 

const LANGUAGE_CONFIGS = {
  javascript: {
    mode: { name: "javascript", json: true },
    mimeType: "text/javascript",
    extension: "js",
    defaultCode: "console.log('Hello World!');",
  },
  python: {
    mode: "python",
    mimeType: "text/x-python",
    extension: "py",
    defaultCode: "print('Hello World!')",
  },
  java: {
    mode: "text/x-java",
    mimeType: "text/x-java",
    extension: "java",
    defaultCode: `public class Main {
    public static void main(String[] args) {
        System.out.println("Hello World!");
    }
}`,
  },
  cpp: {
    mode: "text/x-c++src",
    mimeType: "text/x-c++src",
    extension: "cpp",
    defaultCode: `#include <iostream>
using namespace std;

int main() {
    cout << "Hello World!" << endl;
    return 0;
}`,
  }
};

function Editor({ socketRef, roomId }) {
  const editorRef = useRef(null);
  const [output, setOutput] = useState("");
  const [isRunning, setIsRunning] = useState(false);
  const [currentLanguage, setCurrentLanguage] = useState("javascript");
  const [isCompiling, setIsCompiling] = useState(false);
  const [complexity, setComplexity] = useState("");

  useEffect(() => {
    const init = async () => {
      const editor = CodeMirror.fromTextArea(
        document.getElementById("realtimeEditor"),
        {
          mode: LANGUAGE_CONFIGS[currentLanguage].mode,
          theme: "dracula",
          autoCloseTags: true,
          autoCloseBrackets: true,
          lineNumbers: true,
        }
      );
      editorRef.current = editor;
      editor.setSize(null, "400px");
      
      editor.setValue(LANGUAGE_CONFIGS[currentLanguage].defaultCode);
      
      editorRef.current.on("change", (instance, changes) => {
        const { origin } = changes;
        const code = instance.getValue();
        if (origin !== "setValue") {
          socketRef.current.emit("code-change", {
            roomId,
            code,
            language: currentLanguage,
          });
          analyzeComplexity(code);
        }
      });
    };
    init();
  }, []);

  useEffect(() => {
    if (socketRef.current) {
      socketRef.current.on("code-change", ({ code, language }) => {
        if (code !== null) {
          editorRef.current.setValue(code);
          setCurrentLanguage(language);
          updateEditorMode(language);
          analyzeComplexity(code);
        }
      });

      socketRef.current.on("output-change", ({ output }) => {
        setOutput(output);
        setIsCompiling(false);
      });

      socketRef.current.on("complexity-change", ({ complexity }) => {
        setComplexity(complexity); // Update complexity state
      });
    }
    return () => {
      socketRef.current.off("code-change");
      socketRef.current.off("output-change");
      socketRef.current.off("complexity-change");
    };
  }, [socketRef.current]);

  const updateEditorMode = (language) => {
    editorRef.current.setOption("mode", LANGUAGE_CONFIGS[language].mode);
  };

  const analyzeComplexity = async (code) => {
    try {
      const response = await axios.post("https://api.gemnai.com/analyze", {
        apiKey: "AIzaSyCedNgntzCIHK4HziR8TZRxEgIiUzrTPhg", // Replace with your API key
        code,
        language: currentLanguage,
      });
      const complexityResult = response.data.complexity;

      setComplexity(complexityResult);
      socketRef.current.emit("complexity-change", {
        roomId,
        complexity: complexityResult,
      });
    } catch (error) {
      console.error("Error analyzing code complexity:", error);
    }
  };

  const handleLanguageChange = (selectedOption) => {
    const newLanguage = selectedOption.value;
    setCurrentLanguage(newLanguage);
    updateEditorMode(newLanguage);
    
    // Emit language change to other users
    socketRef.current.emit("code-change", {
      roomId,
      code: LANGUAGE_CONFIGS[newLanguage].defaultCode,
      language: newLanguage,
    });
  };

  const compileAndExecute = async () => {
    setIsCompiling(true);
    const code = editorRef.current.getValue();

    try {
      let result = '';
      if (currentLanguage === 'javascript') {
        const originalConsole = console.log;
        console.log = (...args) => {
          result += args.map(arg => 
            typeof arg === 'object' ? JSON.stringify(arg, null, 2) : String(arg)
          ).join(' ') + '\n';
        };

        eval(code);

        console.log = originalConsole;
      } else {
        result = `Please set up backend compilation service for ${currentLanguage.toUpperCase()}`;
      }

      socketRef.current.emit("output-change", {
        roomId,
        output: result,
      });
      
      setOutput(result);
    } catch (error) {
      const errorMessage = `Error: ${error.message}`;
      socketRef.current.emit("output-change", {
        roomId,
        output: errorMessage,
      });
      setOutput(errorMessage);
    }
    
    setIsCompiling(false);
  };

  const languageOptions = [
    { value: 'javascript', label: 'JavaScript' },
    { value: 'python', label: 'Python' },
    { value: 'java', label: 'Java' },
    { value: 'cpp', label: 'C++' }
  ];

  return (
    <div className="h-screen flex flex-col">
      <div className="bg-gray-800 p-4 flex items-center space-x-4">
        <Select
          value={languageOptions.find(option => option.value === currentLanguage)}
          onChange={handleLanguageChange}
          options={languageOptions}
          className="w-40"
        />
        
        <button
          onClick={compileAndExecute}
          disabled={isCompiling}
          className={`px-4 py-2 rounded-md ${
            isCompiling 
              ? 'bg-gray-600 cursor-not-allowed' 
              : 'bg-green-600 hover:bg-green-700'
          }`}
        >
          {isCompiling ? 'Compiling...' : 'Run Code'}
        </button>
      </div>

      <div className="flex-1">
        <textarea id="realtimeEditor"></textarea>
      </div>
      
      <div className="h-48 bg-gray-900 text-white p-4 font-mono">
        <div className="flex justify-between items-center mb-2">
          <span className="text-gray-400">Output Terminal</span>
          <span className="text-sm text-gray-400">
            Language: {currentLanguage.toUpperCase()}
          </span>
        </div>
        <div className="h-32 overflow-auto bg-black p-2 rounded">
          <pre className="text-green-400">
            {output || `// Ready to run ${currentLanguage.toUpperCase()} code...`}
          </pre>
        </div>
      </div>
    </div>
  );
}

export default Editor;
